<?php
namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class AuthController extends Controller {public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string','device_name'=>'nullable|string|max:100']);$u=\App\Models\User::where('email',$data['email'])->where('active',true)->first();if(!$u||!Hash::check($data['password'],$u->password))throw ValidationException::withMessages(['email'=>'Credenciais inválidas.']);return ['token'=>$u->createToken($data['device_name']??'web')->plainTextToken,'user'=>$u->load('roles','companies')];}public function me(Request $r){return $r->user()->load('roles.permissions','companies');}public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->noContent();}}
